<?php
namespace App\Http\Controllers;
use App\Models\Category; use Illuminate\Http\Request; use Illuminate\Support\Str;
class CategoryController extends Controller { public function index(){return view('categories.index',['categories'=>Category::withCount('products')->latest()->get()]);} public function create(){return view('categories.form',['category'=>new Category]);} public function store(Request $r){$d=$r->validate(['name'=>'required|max:100','description'=>'nullable','is_active'=>'boolean']);$d['slug']=Str::slug($d['name']);Category::create($d);return redirect()->route('categories.index')->with('success','جۆر زیادکرا.');} public function edit(Category $category){return view('categories.form',compact('category'));} public function update(Request $r,Category $category){$d=$r->validate(['name'=>'required|max:100','description'=>'nullable','is_active'=>'boolean']);$d['slug']=Str::slug($d['name']);$category->update($d);return redirect()->route('categories.index')->with('success','جۆر نوێکرایەوە.');} public function destroy(Category $category){$category->delete();return back()->with('success','جۆر سڕایەوە.');} }
